+// Estándar de empresa (brain: estandares/documentos-fiscales.md): SSS-AAAA-NNNNNN.
+// Un valor fuera de rango es un error; nunca se trunca ni se ajusta.
+export function numeroFactura(sucursal, gestion, correlativo) {
+  const entre = (v, min, max) => Number.isInteger(v) && v >= min && v <= max;
+  if (!entre(sucursal, 1, 999)) throw new RangeError("Sucursal inválida: de 1 a 999");
+  if (!entre(gestion, 1000, 9999)) throw new RangeError("Gestión inválida: 4 dígitos");
+  if (!entre(correlativo, 1, 999999)) throw new RangeError("Correlativo inválido: de 1 a 999999");
+  return `${String(sucursal).padStart(3, "0")}-${gestion}-${String(correlativo).padStart(6, "0")}`;
+}
